        internal static string ToStrObject(string str, string[] keys) {            //val="&quot;756, 574&quot;" type="Point" > "{x:756, y:576}"            var values = ToStrArray(str);            var outStr = "{";            keys.ForEach((k, i) => {                // Add comma except the last item                var comma = "";                if (i < keys.Length-1) comma = ", ";                // Add object key and value                outStr += k + ":" + values[i] + comma;            });            outStr += "}";            return outStr;        }//ORpublic static class EnumerableExtensions {    public delegate void ElementAction<in T>(T element, ElementInfo info);    public static void ForEach<T>(this IEnumerable<T> elements, ElementAction<T> action) {        using (IEnumerator<T> enumerator = elements.GetEnumerator())        {            bool isFirst = true;            bool hasNext = enumerator.MoveNext();            int index = 0;            while (hasNext)            {                T current = enumerator.Current;                hasNext = enumerator.MoveNext();                action(current, new ElementInfo(index, isFirst, !hasNext));                isFirst = false;                index++;            }        }    }    public struct ElementInfo {        public ElementInfo(int index, bool isFirst, bool isLast)            : this() {            Index = index;            IsFirst = isFirst;            IsLast = isLast;        }        public int Index { get; private set; }        public bool IsFirst { get; private set; }        public bool IsLast { get; private set; }    }}